begin;
create extension if not exists pgtap with schema extensions;
set local search_path=public,extensions;
select no_plan();
insert into public.exams(id,title,status,scheduled_start_at,scheduled_end_at,created_by)
values('ab000000-0000-4000-8000-000000000001','Integrity disposable fixture','published',now()-interval '1 hour',now()+interval '1 hour','10000000-0000-0000-0000-000000000001');
insert into public.exam_sections(id,exam_id,title,section_type,section_order,duration_seconds) values('ab000000-0000-4000-8000-000000000002','ab000000-0000-4000-8000-000000000001','Module','module',1,600);
insert into public.exam_integrity_settings(exam_id,enabled,enforcement) values('ab000000-0000-4000-8000-000000000001',true,true);
insert into public.exam_attempts(id,exam_id,student_id) values('ab000000-0000-4000-8000-000000000003','ab000000-0000-4000-8000-000000000001','20000000-0000-0000-0000-000000000001');
insert into public.section_attempts(id,exam_attempt_id,section_id,expires_at) values('ab000000-0000-4000-8000-000000000004','ab000000-0000-4000-8000-000000000003','ab000000-0000-4000-8000-000000000002',now()+interval '10 minutes');
create function public.test_integrity_event(kind text,seq integer,age_seconds integer default 0) returns jsonb language sql as $$select jsonb_build_array(jsonb_build_object('eventId',('ab000000-0000-4000-8000-'||lpad(seq::text,12,'0'))::uuid,'sequence',seq,'type',kind,'sectionAttemptId','ab000000-0000-4000-8000-000000000004','observedAt',now()-make_interval(secs=>age_seconds),'metadata','{}'::jsonb))$$;
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select is((select count(*)::integer from public.attempt_integrity_state),0,'students cannot select raw monitoring summaries');
select is((select count(*)::integer from public.integrity_review_actions),0,'students cannot select teacher notes');
select throws_ok($$insert into public.attempt_integrity_events(attempt_id,event_id,browser_instance_id,document_id,sequence,type,category,observed_at,severity,decision) values(gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),gen_random_uuid(),1,'offline','lifecycle',now(),'info','forged')$$,'42501',null,'direct student event writes denied');
select lives_ok($$select public.integrity_sync('ab000000-0000-4000-8000-000000000003','ab000000-0000-4000-8000-000000000010','ab000000-0000-4000-8000-000000000011','[]',true)$$,'register owned session');
select is((public.integrity_sync('ab000000-0000-4000-8000-000000000003','ab000000-0000-4000-8000-000000000010','ab000000-0000-4000-8000-000000000011',public.test_integrity_event('attention_lost',101))->>'count')::integer,1,'attention episode counts once');
select is((public.integrity_sync('ab000000-0000-4000-8000-000000000003','ab000000-0000-4000-8000-000000000010','ab000000-0000-4000-8000-000000000011',public.test_integrity_event('attention_lost',101))->>'count')::integer,1,'replay is idempotent');
select is((public.integrity_sync('ab000000-0000-4000-8000-000000000003','ab000000-0000-4000-8000-000000000010','ab000000-0000-4000-8000-000000000011',public.test_integrity_event('fullscreen_exit',102))->>'count')::integer,1,'fullscreen loss correlates with attention episode');
select is((public.integrity_sync('ab000000-0000-4000-8000-000000000003','ab000000-0000-4000-8000-000000000010','ab000000-0000-4000-8000-000000000011',public.test_integrity_event('clipboard',103))->>'count')::integer,2,'clipboard category counts');
select is((public.integrity_sync('ab000000-0000-4000-8000-000000000003','ab000000-0000-4000-8000-000000000010','ab000000-0000-4000-8000-000000000011',public.test_integrity_event('shortcut',104))->>'count')::integer,2,'restriction cooldown prevents duplicate warning');
select is((public.integrity_sync('ab000000-0000-4000-8000-000000000003','ab000000-0000-4000-8000-000000000010','ab000000-0000-4000-8000-000000000011',public.test_integrity_event('offline',105))->>'count')::integer,2,'connection loss never counts');
select is((public.integrity_sync('ab000000-0000-4000-8000-000000000003','ab000000-0000-4000-8000-000000000010','ab000000-0000-4000-8000-000000000011',public.test_integrity_event('clipboard',106,40))->>'count')::integer,2,'delayed observation never retroactively counts');
select is((public.integrity_sync('ab000000-0000-4000-8000-000000000003','ab000000-0000-4000-8000-000000000010','ab000000-0000-4000-8000-000000000012','[]',true)->>'count')::integer,2,'reload replaces old document without session-overlap warning');
select is((public.integrity_sync('ab000000-0000-4000-8000-000000000003','ab000000-0000-4000-8000-000000000020','ab000000-0000-4000-8000-000000000021','[]',true)->>'count')::integer,3,'second live browser instance creates overlap incident');
select is((public.integrity_sync('ab000000-0000-4000-8000-000000000003','ab000000-0000-4000-8000-000000000020','ab000000-0000-4000-8000-000000000021')->>'reviewRequired')::boolean,true,'threshold flags teacher review');
select is((public.integrity_sync('ab000000-0000-4000-8000-000000000003','ab000000-0000-4000-8000-000000000020','ab000000-0000-4000-8000-000000000021')->>'reviewCycle')::integer,1,'repeated heartbeat does not duplicate threshold crossing');
select is((public.integrity_sync('ab000000-0000-4000-8000-000000000003','ab000000-0000-4000-8000-000000000020','ab000000-0000-4000-8000-000000000021',jsonb_set(public.test_integrity_event('clipboard',108),'{0,sectionAttemptId}','null'))->>'count')::integer,3,'between-module observations do not count');
select is((public.student_attempt_integrity_policy('ab000000-0000-4000-8000-000000000003')->>'count')::integer,3,'student receives own authoritative sanitized summary');
select ok(not(public.student_attempt_integrity_policy('ab000000-0000-4000-8000-000000000003') ? 'reason'),'student policy response excludes private review reasons');
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000002',true);
select throws_ok($$select public.student_attempt_integrity_policy('ab000000-0000-4000-8000-000000000003')$$,'42501','Attempt not found','another student cannot read policy or summary');
select throws_ok($$select public.integrity_sync('ab000000-0000-4000-8000-000000000003',gen_random_uuid(),gen_random_uuid(),'[]',true)$$,'42501','Attempt not found','another student cannot ingest observations');
select set_config('request.jwt.claim.sub','10000000-0000-0000-0000-000000000001',true);
select is((select counted_incidents from public.attempt_integrity_state where attempt_id='ab000000-0000-4000-8000-000000000003'),3,'teacher can read summary');
select lives_ok($$select public.review_exam_integrity('ab000000-0000-4000-8000-000000000001','ab000000-0000-4000-8000-000000000003',null,'ab000000-0000-4000-8000-000000000101','dismiss','OS dialog false positive')$$,'teacher can dismiss with audit reason');
select is((select counted_incidents from public.attempt_integrity_state where attempt_id='ab000000-0000-4000-8000-000000000003'),2,'dismissal recalculates effective count');
select is((select review_required from public.attempt_integrity_state where attempt_id='ab000000-0000-4000-8000-000000000003'),false,'dismissal clears current flag');
select lives_ok($$select public.review_exam_integrity('ab000000-0000-4000-8000-000000000001','ab000000-0000-4000-8000-000000000003',null,'ab000000-0000-4000-8000-000000000101','reinstate','Reviewed additional context')$$,'teacher may reinstate');
select is((select review_cycle from public.attempt_integrity_state where attempt_id='ab000000-0000-4000-8000-000000000003'),2,'reinstatement starts a new unresolved review cycle');
select is((select status::text from public.exam_attempts where id='ab000000-0000-4000-8000-000000000003'),'in_progress','threshold never submits attempt');
select is((select raw_score from public.exam_attempts where id='ab000000-0000-4000-8000-000000000003'),null::integer,'monitoring never changes grades');
select throws_ok($$select public.integrity_sync('ab000000-0000-4000-8000-000000000003',gen_random_uuid(),gen_random_uuid(),'[]',false)$$,'42501','Attempt not found','teacher cannot impersonate a student session');
reset role;
update public.exam_integrity_settings set enabled=false where exam_id='ab000000-0000-4000-8000-000000000001';
select is((select (policy->>'enabled')::boolean from public.attempt_integrity_state where attempt_id='ab000000-0000-4000-8000-000000000003'),true,'existing policy snapshot does not change with exam settings');
insert into public.exam_attempts(id,exam_id,student_id,generation) values('ab000000-0000-4000-8000-000000000030','ab000000-0000-4000-8000-000000000001','20000000-0000-0000-0000-000000000001',2);
select is((select (policy->>'enabled')::boolean from public.attempt_integrity_state where attempt_id='ab000000-0000-4000-8000-000000000030'),false,'retake takes independent current settings');
select is((select counted_incidents from public.attempt_integrity_state where attempt_id='ab000000-0000-4000-8000-000000000030'),0,'retake never inherits incidents');
select is((select count(*)::integer from pg_publication_tables where pubname='supabase_realtime' and tablename in('attempt_integrity_events','integrity_review_actions','attempt_browser_sessions')),0,'raw events notes and sessions are not published');
update public.exam_attempts set status='completed',completed_at=now()-interval '91 days',raw_score=0,total_questions=0 where id='ab000000-0000-4000-8000-000000000003';
select lives_ok($$select public.retain_integrity_history()$$,'retention job removes only aged raw monitoring history');
select is((select count(*)::integer from public.attempt_integrity_events where attempt_id='ab000000-0000-4000-8000-000000000003'),0,'old raw events are purged');
select lives_ok($$select public.recompute_integrity_summary('ab000000-0000-4000-8000-000000000003')$$,'summary recomputation after retention is safe');
select is((select counted_incidents from public.attempt_integrity_state where attempt_id='ab000000-0000-4000-8000-000000000003'),3,'retention preserves historical aggregates');
select is((select count(*)::integer from public.integrity_review_actions where attempt_id='ab000000-0000-4000-8000-000000000003'),2,'retention preserves review history');
update public.exam_integrity_settings set enabled=true,enforcement=false where exam_id='ab000000-0000-4000-8000-000000000001';
insert into public.exam_attempts(id,exam_id,student_id,generation) values('ab000000-0000-4000-8000-000000000040','ab000000-0000-4000-8000-000000000001','20000000-0000-0000-0000-000000000001',3);
insert into public.section_attempts(id,exam_attempt_id,section_id,expires_at) values('ab000000-0000-4000-8000-000000000041','ab000000-0000-4000-8000-000000000040','ab000000-0000-4000-8000-000000000002',now()+interval '10 minutes');
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select lives_ok($$select public.integrity_sync('ab000000-0000-4000-8000-000000000040',gen_random_uuid(),gen_random_uuid(),jsonb_set(public.test_integrity_event('clipboard',150),'{0,sectionAttemptId}','"ab000000-0000-4000-8000-000000000041"'),true)$$,'logging-only ingestion succeeds');
reset role;
select is((select counted_incidents from public.attempt_integrity_state where attempt_id='ab000000-0000-4000-8000-000000000040'),0,'logging-only policy never increases warning count');
select is((select decision from public.attempt_integrity_events where attempt_id='ab000000-0000-4000-8000-000000000040'),'logging_only','logging-only evidence is retained with explicit classification');
update public.profiles set role='teacher' where id='20000000-0000-0000-0000-000000000005';
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000005',true);
select is((select count(*)::integer from public.attempt_integrity_events),0,'teacher B cannot read teacher A events');
select throws_ok($$select public.review_exam_integrity('ab000000-0000-4000-8000-000000000001','ab000000-0000-4000-8000-000000000003',null,null,'note','Unauthorized review')$$,'42501','Exam not found','teacher B cannot review teacher A attempt');
reset role;
update public.profiles set is_active=false,deactivated_at=now() where id='20000000-0000-0000-0000-000000000001';
set local role authenticated;
select set_config('request.jwt.claim.sub','20000000-0000-0000-0000-000000000001',true);
select throws_ok($$select public.integrity_sync('ab000000-0000-4000-8000-000000000003',gen_random_uuid(),gen_random_uuid(),'[]',true)$$,'42501','Attempt not found','inactive account cannot ingest');
select * from finish();
rollback;
